import java.util.*; class Solution { public int findMinMoves(int[] machines) { int n = machines.length; int total = 0; for (int m : machines) total += m; if (total % n != 0) return -1; int target = total / n; int maxMoves = 0; int currentBalance = 0; for (int m : machines) { int diff = m - target; currentBalance += diff; maxMoves = Math.max(maxMoves, Math.max(Math.abs(currentBalance), diff)); } return maxMoves; } }